22	
23	public final class CompletableFromCallable extends Completable {
24	
25	    final Callable<?> callable;
26	
27	    public CompletableFromCallable(Callable<?> callable) {
28	        this.callable = callable;
29	    }
30	
31	    @Override
32	    protected void subscribeActual(CompletableObserver observer) {
33	        Disposable d = Disposable.empty();
34	        observer.onSubscribe(d);
35	        try {
36	            callable.call();
37	        } catch (Throwable e) {
38	            Exceptions.throwIfFatal(e);
39	            if (!d.isDisposed()) {
40	                observer.onError(e);
41	            } else {
42	                RxJavaPlugins.onError(e);
43	            }
44	            return;
45	        }
46	        if (!d.isDisposed()) {
47	            observer.onComplete();
48	        }
49	    }
50	}
