49	    static final class ElementAtSubscriber<T> implements FlowableSubscriber<T>, Disposable {
50	
51	        final SingleObserver<? super T> downstream;
52	
53	        final long index;
54	        final T defaultValue;
55	
56	        Subscription upstream;
57	
58	        long count;
59	
60	        boolean done;
61	
62	        ElementAtSubscriber(SingleObserver<? super T> actual, long index, T defaultValue) {
63	            this.downstream = actual;
64	            this.index = index;
65	            this.defaultValue = defaultValue;
66	        }
67	
68	        @Override
69	        public void onSubscribe(Subscription s) {
70	            if (SubscriptionHelper.validate(this.upstream, s)) {
71	                this.upstream = s;
72	                downstream.onSubscribe(this);
73	                s.request(index + 1);
74	            }
75	        }
76	
77	        @Override
78	        public void onNext(T t) {
79	            if (done) {
80	                return;
81	            }
82	            long c = count;
83	            if (c == index) {
84	                done = true;
85	                upstream.cancel();
86	                upstream = SubscriptionHelper.CANCELLED;
87	                downstream.onSuccess(t);
88	                return;
89	            }
90	            count = c + 1;
91	        }
92	
93	        @Override
94	        public void onError(Throwable t) {
95	            if (done) {
96	                RxJavaPlugins.onError(t);
97	                return;
98	            }
99	            done = true;
100	            upstream = SubscriptionHelper.CANCELLED;
101	            downstream.onError(t);
102	        }
103	
104	        @Override
105	        public void onComplete() {
106	            upstream = SubscriptionHelper.CANCELLED;
107	            if (!done) {
108	                done = true;
109	
110	                T v = defaultValue;
111	
112	                if (v != null) {
113	                    downstream.onSuccess(v);
114	                } else {
115	                    downstream.onError(new NoSuchElementException());
116	                }
117	            }
118	        }
119	
120	        @Override
121	        public void dispose() {
122	            upstream.cancel();
123	            upstream = SubscriptionHelper.CANCELLED;
124	        }
125	
126	        @Override
127	        public boolean isDisposed() {
128	            return upstream == SubscriptionHelper.CANCELLED;
129	        }
130	    }
131	}
