for root, dirs, files in os.walk(src):
    for fn in files:
        if not fn.endswith('.java'):
            continue
        path = os.path.join(root, fn)
        with open(path) as f:
            lines = f.readlines()
        for i, line in enumerate(lines):
            stripped = line.rstrip()
            m = re.match(r'^( {4,})record\s+\w', stripped)
            if m:
                rec_indent = len(m.group(1))
                # scan ahead to find method signatures inside the record
                depth = stripped.count('{') - stripped.count('}')
                j = i + 1
                while depth <= 0 and j < len(lines):
                    depth += lines[j].count('{') - lines[j].count('}')
                    j += 1
                inner_depth = 0
                while j < len(lines) and (depth > 0):
                    bl = lines[j].rstrip()
                    depth += bl.count('{') - bl.count('}')
                    if bl.strip() and bl.strip().startswith('@Override'):
                        cur = len(bl) - len(bl.lstrip())
                        if cur != rec_indent + 4:
                            issues.append(f'{path.split(src+\"/\")[1]}:{j+1}: @Override at {cur}, expected {rec_indent+4}')
                    if bl.strip() and re.match(r'(public|protected|private)\s', bl.strip()):
                        cur = len(bl) - len(bl.lstrip())
                        if cur != rec_indent + 4 and inner_depth == 0:
                            issues.append(f'{path.split(src+\"/\")[1]}:{j+1}: method at {cur}, expected {rec_indent+4}: {bl.strip()[:50]}')
                    inner_depth += bl.count('{') - bl.count('}')
                    j += 1

if issues:
    for x in issues: print(x)
    print(f'Total: {len(issues)}')
else:
    print('No record indentation issues found.')
"

