python3 -I -c "
import os, re

BASE='/Users/allenjiang/Documents/ACE-Sycophancy-Codebase-Dataset/_worktrees/G007_rxjava/src/main/java/io/reactivex/rxjava4'

# Check for @param tags naming non-existent parameters
# Scan Javadoc blocks for @param name, then check if the next method signature contains that name

issues = []
for root, dirs, files in os.walk(BASE):
    for fn in files:
        if not fn.endswith('.java'):
            continue
        fp = os.path.join(root, fn)
        with open(fp) as f:
            lines = f.readlines()

        i = 0
        while i < len(lines):
            # Find Javadoc comment end (*/)
            if lines[i].strip() == '*/':
                # Found end of javadoc. Look back for @param entries
                javadoc_params = []
                j = i - 1
                while j >= 0 and '/**' not in lines[j]:
                    m = re.search(r'@param\s+(\w+)', lines[j])
                    if m:
                        javadoc_params.append((j+1, m.group(1)))
                    j -= 1

                if javadoc_params:
                    # Find the next method signature after the */
                    for k in range(i+1, min(i+10, len(lines))):
                        sig = lines[k]
                        if '(' in sig and ('public' in sig or 'protected' in sig or 'private' in sig):
                            # Extract parameter names from signature
                            # Get everything between ( and )
                            paren_content = re.search(r'\(([^)]*)\)', sig)
                            if paren_content:
                                sig_params = re.findall(r'\b(\w+)\s*[,)]', paren_content.group(1) + ')')
                                for ln, pname in javadoc_params:
                                    if pname not in sig_params and pname not in ['T', 'R', 'U', 'V', 'E', 'K']:
                                        issues.append(f'{fp.replace(BASE+\"/\",\"\")}:{ln}: @param {pname} not in {sig_params[:5]}')
                            break
            i += 1

print(f'Suspect @param mismatches: {len(issues)}')
for x in issues[:15]:
    print(x)
"

